using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public class CouncilInputTests
{
    static WorldSession New(bool refuses=false){var s=new WorldSession(MissionEntry.Create(refuses));Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);return s;}
    static RegionalRequest Line(WorldSession s,string id="request:chosen",bool own=false)=>CouncilInput.Line(s.DiagnosticSnapshot(),id,own?ContractFixture.Officer:ContractFixture.Clerk,ContinuousWorld.Point("castle",own?65000:95000,own?-85000:-65000),ContinuousWorld.Point("castle",own?85000:115000,own?-85000:-65000));
    [Fact] public void ComposingPreservesWorldAndSelectedEndpoints(){var s=New();var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());var r=Line(s);Assert.Equal(ContractFixture.Clerk,r.Recipient);Assert.Equal(ContinuousWorld.Point("castle",95000,-65000),r.A);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void PhysicalDeliveryPrecedesFormationAndReportKnowledge(){var s=New();var r=Line(s);var before=s.DiagnosticSnapshot().Region!.Units.Select(u=>u.Position).ToArray();Assert.Equal(ResultCode.Accepted,s.IssueRegional(r,s.Revision).Code);Assert.Equal(before,s.DiagnosticSnapshot().Region!.Units.Select(u=>u.Position));var due=s.DiagnosticSnapshot().Region!.Deliveries.Single().DueAt;s.AdvanceTo(due-1);Assert.Equal(before,s.DiagnosticSnapshot().Region!.Units.Select(u=>u.Position));s.AdvanceTo(due);var w=s.DiagnosticSnapshot();Assert.Equal("applied",w.Region!.Commands.Single().Result);Assert.Equal("発送済・結果未確認",RegionalBattle.Status(w,w.Region.Commands.Single(),ContractFixture.Officer));s.AdvanceTo(250);w=s.DiagnosticSnapshot();Assert.Equal("applied",RegionalBattle.Status(w,w.Region!.Commands.Single(),ContractFixture.Officer));Assert.All(w.Region.Units.Where(u=>u.Commander==r.Recipient),u=>Assert.Equal(u.Goal,u.Position));}
    [Fact] public void OwnOrderUsesNoFakeCourierOrPermissionTransfer(){var s=New();var w=s.DiagnosticSnapshot();var r=Line(s,own:true);Assert.Equal(ResultCode.Accepted,s.IssueRegional(r,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Region!.Deliveries);Assert.Equal("applied",s.DiagnosticSnapshot().Region!.Commands.Single().Result);Assert.Equal(ContractJson.Write(w.Grants),ContractJson.Write(s.DiagnosticSnapshot().Grants));}
    [Theory][InlineData(0)][InlineData(9999)] public void TooShortLineIsRejected(int length){var s=New();var a=ContinuousWorld.Point("castle",95000,-65000);Assert.Throws<InvalidDataException>(()=>CouncilInput.Line(s.DiagnosticSnapshot(),"request:short",ContractFixture.Clerk,a,a with{X=a.X+length}));}
    [Fact] public void UnknownRecipientCannotBeComposed(){var s=New();Assert.Throws<InvalidDataException>(()=>CouncilInput.Line(s.DiagnosticSnapshot(),"request:enemy",RegionalBattle.Enemy,new(0,0),new(20000,0)));}
    [Fact] public void NoCommandAuthorityLeavesWorldUnchanged(){var w=New().DiagnosticSnapshot();w.Grants=w.Grants.Where(g=>g.Agent!=ContractFixture.Officer||!g.Actions.Contains(ActionKind.Move)).ToArray();var s=new WorldSession(w);var hash=ContractJson.CanonicalHash(w);Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(Line(s),s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void MissingServiceBondDoesNotCreateCommandRights(){var w=New().DiagnosticSnapshot();w.ServiceBonds=w.ServiceBonds.Where(b=>b.Subject!=ContractFixture.Clerk||b.Target!=ContractFixture.Officer).ToArray();var s=new WorldSession(w);Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(Line(s),s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Region!.Commands);}
    [Fact] public void RepeatedRequestDoesNotDispatchAgainAndChangedLineConflicts(){var s=New();var r=Line(s);s.IssueRegional(r,s.Revision);Assert.Equal(ResultCode.AlreadyAccepted,s.IssueRegional(r,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.IssueRegional(r with{B=r.B with{X=r.B.X+1000}},s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Region!.Commands);Assert.Single(s.DiagnosticSnapshot().Region!.Deliveries);}
    [Theory][InlineData(false)][InlineData(true)] public void RefusalOrUnwalkableGoalIsReportedWithoutMoving(bool refuses){var s=New(refuses);var r=Line(s);if(!refuses)r=r with{A=ContinuousWorld.Point("castle",45000,85000),B=ContinuousWorld.Point("castle",65000,85000)};var positions=s.DiagnosticSnapshot().Region!.Units.Select(u=>u.Position).ToArray();s.IssueRegional(r,s.Revision);s.AdvanceTo(250);var w=s.DiagnosticSnapshot();Assert.Equal(refuses?"refused":"blocked-hold",RegionalBattle.Status(w,w.Region!.Commands.Single(),ContractFixture.Officer));Assert.Equal(positions,w.Region.Units.Select(u=>u.Position));}
    [Theory][InlineData(0)][InlineData(10)][InlineData(40)] public void SavingChosenOrderRetainsGeometryDeliveryAndOutcome(int at){var s=New();s.IssueRegional(Line(s),s.Revision);s.AdvanceTo(at);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"council-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"stage",w.WorldId,new(0,10,CouncilOpen:true));var host=new WorldSessionHost(new(MissionEntry.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("stage"),host.Current,host.Current.Revision));host.Current.SetPaused(false);s.AdvanceTo(250);host.Current.AdvanceTo(250);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Region),ContractJson.Write(host.Current.DiagnosticSnapshot().Region));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Messaging),ContractJson.Write(host.Current.DiagnosticSnapshot().Messaging));}
}
